    (4148, 46, 6, 148, 'Then I''ll visit the market ten minutes away.', 'Not really. It''s ten minutes away on foot.', 'a3d6235d91e3e0d5517926b0e4c0902a3cd89737d25bfa9904fd21b9ce87c4ab', '6e348476bf88edcb6c20cd5410f5e29f95387158d456d49775bead6829f8ba97'),
