    (4268, 49, 6, 268, 'I know, so something light and cold would be perfect.', 'Let''s get something light because we ate an hour ago.', '3dfb7702d1f78c3b838854098cf87f3782370732ce27628c0ac7d80f293bb765', 'd7e31c51a2c9683134d4ee3d8cae6715db336a140bc50faedcc6e0db65789748'),
    (4269, 49, 7, 269, 'I''ve never tried a pub quiz, but it sounds fun.', 'I''ve never tried cider before, but I''ll give it a go.', '6cbfeb2c1f8a9f10acdfe7ce05fc1d76263b22b00966ef7385d1dcb046e50e05', 'e6b37935834d8f1da6ada889edf29f1fda68a23bf5a5ba6762a010756ab47a20'),
    (4270, 49, 8, 270, 'Put it on one bill and we''ll pay all together.', 'No need, my colleague will pay all together for us.', 'cd8fa243bb424f3e6f0647b1f08d26f7f10921baf9a04222873f42fa602af73e', 'f239da1654b307968770e900cc1af6db90d37402ff8bafb8d84636078e18bb67'),
    (4271, 49, 9, 271, 'Beer always tastes better on tap.', 'The new place has local beers on tap.', 'f1060c22f9b76f058b9b96da105b4a02a12a42f5e754562d9d9055c9860a46f3', 'cca4eee04d65b88991c240c51b19eefca0de305ef9020efcebf2fa88c8fc9a46'),
    (4272, 49, 10, 272, 'What are you having? I''ll have the same.', 'Actually, I''ll have the pasta instead.', 'b81815c883f5fef972cab58e6defa0533f499a4a4f80389c2c406ff1ef7050d9', '828b3aa25fb49e0fdb041711cc1e9e47b8b03425ee12e988c3958e0e58bab2e7'),
    (4273, 49, 11, 273, 'He forgot to close his tab last night.', 'Put it on my tab, please.', '669f211145a9834d4c650a08cd656e881e385a625a0f4a72eda60b1a6dbba847', '76f9b3f41beb2f2ac60b23fa4ce2f437e5c6e0cfc8f02c340beb37e804d66913'),
    (4274, 53, 1, 274, 'Strong tea, please, but in a bigger cup.', 'Strong tea, please, for both of us.', '487dc4bbdfbd5b70957315e074283a016880713f1fa197313b4a85434a3a4186', '03f18f94cc70dea562116456d44c3d45bf31dbbacd4676548dba0560ca1c2088'),
    (4275, 53, 2, 275, 'Honey, because I like something sweet.', 'I always eat something sweet after lunch.', 'ae7c232dfbe1921bee2614e17c17885bae4a5d975f572aa2005c86079d3aca6d', '07845e48c6b472e8c2f4de05851c08b0215793c04cd9caa04e4732eb9c5edcec'),
    (4276, 53, 3, 276, 'Yes, I always start with cream first.', 'Yes, please, because I eat cream first.', '5db6da475c0fff2d1ab514ae08cfce62c84cd9a275e7db02a01c1a687f94e5f4', 'a772f9c693f28750d0609692b26cc4b1a212dd267bc7c314d5e21036b2a32d67'),
    (4277, 53, 4, 277, 'No, thank you, just one more cup.', 'Okay, but I need one more cup.', 'e081448d9fe6e2f0383acbbb3c3ebdf3cde9b8f47e7539a66281be671910cea6', 'aca8022e2759d23c083af60c3c2b95e6390e010c97ce2d5515e67362cf2e2d19'),
    (4278, 53, 5, 278, 'I prefer something bigger, so a pot please.', 'No thanks, I prefer something less sweet.', '401cd83ee53582e5633355fc90b077b95f489e627547c8b27215d9c61ae0c98b', '4687a3bebf6db9713301fc59f4032e51ae4e80420141785d229b0c91708c79fd'),
    (4279, 53, 6, 279, 'I know, it''s hard to spread cream on a soft scone.', 'We often spread egg salad on white bread.', '2ee706f26e37d3d5fec3f516609f1d9eb03f4dbf4c25ef5c11f9cb81f959fc98', '952d1d2523af8128902768ed32646cb54b26e14f70216f2c47fc3fddfb779fdf'),
    (4280, 53, 7, 280, 'I still want to learn the traditional way today.', 'At home we do, but today I want the traditional way.', '81efcb23c88aa6dd370d3b9971f2a52cf32e898a00cfb55c5a374410aacdd664', '90ce8dd498a652234ee313f147bd0cd93ee67f24c31461cea265f9224097ff67'),
    (4281, 53, 8, 281, 'Sweeter than I expected, so I''ll try a different one.', 'Then I''d love to try a different one every visit.', 'bb357a97d44ab50b7696adf834e1601f8ec5c5a6b3385b3831cbd7947397b277', 'a2121ae2edbabd2f67bbced2832559e1553e0e72f569269286948cdc5cd40f8d'),
    (4282, 53, 9, 282, 'That scarf goes really well with your coat.', 'Does this color go well with the walls?', 'cf4b74b966f18140264631329615e8d59673dd895c43a0a8ef198a8729bfe4a0', '8adced1670bba9332066f68cd55d079b29ea326ad5b21b81b1eb0aeb6794f24a'),
    (4283, 53, 10, 283, 'He got a refill before the movie started.', 'Is the refill free, or do I pay again?', 'f54d8788ee9144e230a2a444956fc026b96003ae491ecaf49df022c7bc4ccff5', 'f1d01bbe52e18ebec7cf4fa5d5b53a2dbf4f0645459b79622e8ba5182e098725'),
    (4284, 53, 11, 284, 'She brewed a pot of coffee for everyone.', 'A pot of chamomile before bed helps me sleep.', 'c1ce09f52dcae4706ce937b67da3e3f2855060def1d12f851ad145849e31af5a', '1ac31c253b043c5c30d6caeaa4a206a8f72d8972a6119a2fec92b3e7dd062da7'),
    (4285, 61, 1, 285, 'No, just the same style and color.', 'Not today, the same style is fine.', 'ed206f723ba0d2f272b1484cf3cb57e9c5bf811c52c4289f97d33cf91a83030b', '9f4a9ebc4d80ddfdb466cec1074863621e49438784e2afe3635ecc8279034a4b'),
    (4286, 61, 2, 286, 'The back can be a little shorter.', 'Every month, and always a little shorter.', 'b148122b4f84d7072635495d2f409eca55c63d7377a672c18b1a7978dcfaa3f8', 'b176380c2a84759ac15470bfbe83d65ff101f5b19e7a360ee7f4c06869a20f20'),
    (4287, 61, 3, 287, 'Thank you, but the front too, please.', 'Okay, but please check the front too.', 'd327197019e0fa862dcef64c71979ce2501753560ee72ac793e09528f81ff379', '01eaad3fee1ec7f5f11345df672902a9fe3e31f3f6276fbda9263554767c64fa'),
    (4288, 61, 4, 288, 'It is perfect, much better than before.', 'No need, it is perfect already.', '1e0ddfa57ff2bcf1860d7e6005a4f6bbbdd912239f1d243235334cf1ca9a6c7e', '19ddeeb10de9589ac5631147687cb451a207d4982a4c23339f41bf99b4be5681'),
    (4289, 61, 5, 289, 'Not exactly, I just want something different from this.', 'A wedding next month, so I want something different.', 'cff70f9d42328e5ecddabfab6c5be39d7693fa3f6101fabfc7d42cc6505ec436', '7fcb7f3c4338307ab283d0371b2996a064ec763cc054354ceb19bb79e796ab4d'),
    (4290, 61, 6, 290, 'I know, so add some layers to make it lighter.', 'Just a quick blow dry, so add some layers to help.', '07763fd0b70c81e04bb8c8b59461a7a1cc55bd3ef305c4a3a86fc90d2553c514', '9d3273d92775ecb29220be26eefb9da62bc9db87f7f191f621a9d9ad0e9de638'),
    (4291, 61, 7, 291, 'Yes to the fringe, but keep the length at the back.', 'Cut only the damaged part and keep the length, please.', '8587307df0b302b585eea4cbfe035180e52356d6bd8ac0baf55e210297801bfd', '49c70568229141411b053275099a4be12acf1d1077b30c1a2eaeba63d7ade62a'),
    (4292, 61, 8, 292, 'Yes please — oh, it''s exactly what I wanted.', 'So much lighter, it''s exactly what I wanted.', '9fecc5a09ef76ea45e33f6c153d84975291437b9e78cc5b97409d07d2d66a504', '8ee6b402181e9735bd592ee4e3db531a174f33d6af650de0ff0c4279e389c195'),
    (4293, 61, 9, 293, 'He got a quick trim before the interview.', 'Just a trim today, or a new style?', '27bc0f4183faff83ac7900ef8ad156f0e0a1089a02e7176d7ab7cf7401268185', 'cc571f73bada2fbf064b6de1c269b23d77752c37ec3115ee5febaee449a00fb7'),
    (4294, 61, 10, 294, 'The crowd thinned out after the fireworks.', 'Don''t thin it out too much, please.', '6d54ab05fece5b3f63e219abe503c935b4349b3313a1fd8b41131a6e785f39eb', '0f9ab72ad8daf20b713fc10a36507c1d10661dc37f18e8eff6b6474b429ddaf8'),
    (4295, 61, 11, 295, 'Growing it out is the hard part.', 'Should I cut it short or grow it out?', '9a20418624913d0449dbf3fded89c6183ac911316ef33e31dcb19bdf1d7a014b', '428cb230e855fa61fdf0a1fd69795b4a3cc3c2b8a4b981766e2d32c3296d2298'),
    (4296, 63, 1, 296, 'I''d like that a lot.', 'Yes, please. I''d like that.', 'd20ba7242e49a6b6edd80ac7694693ddbb9768d50c6e35cd08c1edf9a7c7203e', '1a1e2f0498f9cc3f05a7c89957d7e7f4727c14092658c594ed3b60b5b19f8f50'),
    (4297, 63, 2, 297, 'Good, I can play then.', 'Yes, I can play tomorrow.', '50c106ff8bbfb7334110ccba37c80f1fda616c4d3f7397f1334921266852033b', '5e7602a85a09c6345bc822f9a972a5a8002fbea3ea3f45cca6be5d0f714a7db3'),
    (4298, 63, 3, 298, 'Yes, I know a lot about football.', 'I know a lot about cars.', '2bc7f6e7f139d1501367fe874a31272e7a58a26e6140f1dd2406f59456e44b77', '1eb2ed980e2b79fe913cdbaa6dc806f2f1bb69e9009011620d63451036228a20'),
    (4299, 63, 4, 299, 'Let''s call it Sunshine Tea.', 'Cute! Let''s call it Lucky.', '42b5e127a0202e8a5e94f3cd9ddc8888b29c086a5110adc9f588a058056f8622', 'f9ea6016a830b738cfabb7a3966c29b078cf8947aa00db8c9617a5360005420c'),
    (4300, 63, 5, 300, 'That sounds fun. Can I join a team?', 'He could join a team and make friends there.', '492ec98dcf01da0e7d00f861d5722eeabdefd3b3cc62f991ee76e62b4bbfcccf', '154aee5be724877c454617a7cc7145c03686f5425ef2f15f2d57795cf6f3cd23'),
    (4301, 63, 6, 301, 'My strong point is history, not maths.', 'My strong point is taking photos, so I can help.', '8949e41378b6d009ec5967d65ecfa5ca12584e1283d31d73e8b184207f7599bc', '1c7d68408d7e9d217fda95eb499f908c6fcd53edd22fb48556a6e7db8a9f5e36'),
    (4302, 63, 7, 302, 'Yes, but I can''t think of a name for it.', 'Let me think of a name tonight.', 'f807186e7604c75c772969c3843df5ad9ed1bf089a39f908235d5bf547e913aa', 'fedaf628c7b4bfe47cd093af5b0030856f716bb92b55693a8324874f8ddf8a9f'),
    (4303, 63, 8, 303, 'Let''s go with eight, it''s easier for me.', 'Let''s go with the blue logo.', '41d448fb87bca0109062d1c8c551c578a035806c8d5ccf467d3b9f06abba2183', 'f0c1e52fffecdbd5c120fdbc5c23e678d850d9a5dc5d51a0a69d551917604bf9'),
    (4304, 63, 9, 304, 'The kids joined in the game right away.', 'Don''t be shy — join in the conversation.', '3946fdffcdb58f53d85f94bac7c0358fb0e6894da4d8ab7813bd41c6bf56c6d3', 'b84312cfd8ed4f21cfe01179e3dcfa574dd215ee06d301980dabb3d01cd003db'),
    (4305, 63, 10, 305, 'I gave surfing a go last summer.', 'If it doesn''t work, at least we gave it a go.', 'f0470e6b36482694be8d3f8fa2bdbd12f06b1be2c930b38129c189d5e8f24f7d', '8b3425291db2bda9f6629f56fc6f97aed80746566fc8b312f6922939d2e47fcb'),
    (4306, 63, 11, 306, 'Trust me, I know a thing or two about moving.', 'He''s been cooking for years — he knows a thing or two.', 'bd9e7bbf307ed48fcbe5710798c0658d7fe15fadd26d0a4f56ee3dc7b6472115', 'a5aba94dc220da58f7ee45fab733269e38134b4e39c411b7b566c6cdfd24af37'),
    (4307, 69, 1, 307, 'No, I took the bus today.', 'No, I took the bus to the station.', 'd7690f1881705f25dee1a2f64d917c5961970db98ed937c082f24e05456a4754', '0c08d7dd5a3628e8fd1fb88aa308b2ff412743d0c55bf35ec7bec6b8b4dc12be'),
    (4308, 69, 2, 308, 'Then I should get my money back.', 'How can I get my money back?', '26ddeb1191a886435e4298b918b50c3fec7a5b3eb0a0f7ef28396a4e48b95391', '90ad09fdcb3bdad5458f875fc00c10050a91fcb09760960e7f60df242032f7ba'),
    (4309, 69, 3, 309, 'Only three more days, sadly.', 'We need three more days.', 'f50107c69afbbd5636e18c70a3923926986dac1ffc16bde49325b1c1f13d05a4', '307a2ef8ba02425af148839f064bc97cdeed5c34ad348ba9567d12a5777db841'),
    (4310, 69, 4, 310, 'I ride every day after school.', 'I ride every day for an hour.', 'e0aa3d6edb2c4285d7fd2c9812256edd1f671fce78cf1dbc24486fe850edd993', 'faac1beb50359edea052c6417e140046a8d0ec3917410933e0416801edf5e010'),
    (4311, 69, 5, 311, 'I had to transfer to another train twice.', 'Not now. You can transfer to the tram at City Hall.', 'a2a0cf747fe633c9aae332e7e6349cbd91b46ea9482092283802881cb71b1167', 'f25e49986419482c01fd50d3b623e279de0f76313a63f9911f05ac3137963d81'),
    (4312, 69, 6, 312, 'I need to get to the station fast, then.', 'I need to get to the airport by eight.', 'c16525c09bca35fd5a065749ad3b05e98462523e77ca51e8545b5d5c98ca5ac3', '99e5103f0c26ddbb509292b2fd9f6d1d1a7c13c8a8635612766ffca069925b8d'),
    (4313, 69, 7, 313, 'Yes, he''s with us until Friday morning.', 'They''re away until Friday, I think.', '90ffd35365aa5dd3e684f5d6cbbb02af1e5787ab88cf9defe31e78b6b07fd091', 'e42c1e02a2649879474e261da3b675d72d146b6a5007cc37f042420db0099862'),
    (4314, 69, 8, 314, 'I do, and it''s worth it every time.', 'It is, but the rent is cheap, so it''s worth it.', '8af7ba2d77cf8513aa11f371715d0f65eb6bb152659635dcc1fd75cbb3d0f875', '1903026f9ebd1db3f69fa0e43e8886cf2817498f60b1ad23fedd62dbf0970ec7'),
    (4315, 69, 9, 315, 'I tapped my card twice by mistake.', 'Tap here and the doors will open.', 'b0c0b2a609547a497f0f19f3762a0b741e398d94fa949652e140d3a664f5a850', '0c3c1e41e7263fecbea7d662eb5bc31c4f407681e7007909134202005ac379b8'),
    (4316, 69, 10, 316, 'If you''re overcharged, ask for a refund.', 'The hotel overcharged us for the minibar.', '81833ba6576d953feb4659b006ef90092008455186d32c51d0876d8731b8c976', 'e944c5705f1a7d96898154e899593e64d8f4b5c5ecb35689b3e9655383aa0d03'),
    (4317, 69, 11, 317, 'The gym is empty during off-peak hours.', 'Is this ticket valid off-peak only?', '039e4d58423c1a6c5f9f5c142ccde08e3c869f25d0ab473dc3733cdb5d66a9b0', '6495fe1cfc9539dad754a8c2d23890e2eca083b4e695dc3b0c554c62690defb1'),
    (4318, 66, 1, 318, 'Yes, I have two hours now.', 'I have two hours to study.', '88e2951b36884d392ba7f18fba4c0caa95e21a9801780deff74f4682890a2e21', '569a3be3ca19d4d5f9ad4f71946893859e1632f515f33e4ca615576ea1333994'),
    (4319, 66, 2, 319, 'Then let''s take an easy walk.', 'The river path is an easy walk.', '19610a0a50d68bcc50be5f4e7f38d86ead2bf8cfa283a8fe85e621a4a66dc04b', '18336e0b3c85c8cc2faa1a089cde78f22735cf164328b55d3cc7aedcefdba918'),
    (4320, 66, 3, 320, 'Sure, I have my camera with me.', 'No, I have my dog with me.', 'acfff92f887cbab7bde45ffa6e058465760d9601bf4eab2a1d04a7aefbcea320', '88820d399d4dfa31f45b464e902fb4bba6efcc07ad97eb89997ac0bc89eb802d'),
    (4321, 66, 4, 321, 'No, I wore a raincoat.', 'He can borrow a raincoat from me.', 'bbb96449ea179ec4e0b93ae4763b94a5f8c947013c362415c585144891f52e35', 'fc8f42ac8ed1026929bcfb2cb3fbc0b5748c1e2eb705f900eda5bee83763de60'),
    (4322, 66, 5, 322, 'Yes, let''s go hiking early before it gets hot.', 'I go hiking in the mountains every month.', '47d3ebbfe2a42214f5581c2f773b37a14f3db479a27c5b76eb30eb39b26e577a', '09c469763b01abeec7b1ce7384075b2b02e0576f709a305195b2afd127f1584f'),
    (4323, 66, 6, 323, 'Let''s cook the easy one, I''m tired.', 'Everyone wants the easy one, of course.', 'bbcceb15a59169ec04451b31df5edd86dcc2ea4567e6a1856ff656f01f12ec4a', 'd0a21136bcdaf7439da08974b2c57cc6e050dcf151fa7df52cec6db7e4c9a245'),
    (4324, 66, 7, 324, 'Yes, it''s right here in my backpack.', 'Not really, I carry it in my backpack.', 'eebc9db373608703cb887e5222fbb5095d0d437a985b0c9faf9160d71f588bb3', '463e33f9d291625b102ec00c5ea40bc6383c1f8c0e73abd28b9619bf410a164c'),
    (4325, 66, 8, 325, 'I didn''t drink enough water that morning.', 'There''s enough water for both of us.', '388e31ebae22960c10abd642bd284e8155bc91951439cf066742dd331222955c', '9af40ae006bd493504a099e88e436b35c5bb9f1123fb9dbec9dc1f612dca53c7'),
    (4326, 66, 9, 326, 'Careful — the driveway is steep and icy.', 'Fifty dollars for pasta? That''s steep.', 'c6f2fa6d74a0c37761daba9e8beacaef0795440ac6a048bbeae0647365b5b98c', '536f660d2313292fa3d30052cfb4698078f46b4030dab1abe4782e0228b5995b'),
    (4327, 66, 10, 327, 'We packed rain gear just in case.', 'Does the shop rent out rain gear?', 'e54e440e3c0d2bd5cf89242be1254b87ff1cba0ab3252fe474cd90ae6eddf775', '41baa66463ccadca950d9ba22d02b28b34ce7e5d91b59173eb3c9b923f89df00'),
    (4328, 66, 11, 328, 'She finally made it to the top of her field.', 'Halfway there — we''ll make it to the top soon!', '51fc1ea926489fe51b2196e69100d83023415b7bdd78829b43fb3104eaaa1ec9', 'f7dd3f2104a7053dd5aa8ea2b91fbf4ae2e5948a69ca93de67eced9b193c4e64');

DO $$
DECLARE
    affected_rows INTEGER;
BEGIN
    IF (SELECT count(*) FROM lan391_practice_image_map) <> 328 THEN
        RAISE EXCEPTION 'LAN-391 image mapping requires 328 expressions';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM lan391_practice_image_map asset
        LEFT JOIN writing_expression expression ON expression.id = asset.expression_id
        WHERE expression.id IS NULL
           OR expression.scenario_id IS DISTINCT FROM asset.scenario_id
           OR expression.display_order IS DISTINCT FROM asset.expression_display_order
           OR jsonb_typeof(expression.practice_examples_payload) IS DISTINCT FROM 'array'
           OR CASE WHEN jsonb_typeof(expression.practice_examples_payload) = 'array'
                   THEN jsonb_array_length(expression.practice_examples_payload)
                   ELSE -1 END <> 4
           OR expression.practice_examples_payload->2->>'sentenceText' IS DISTINCT FROM asset.example3_sentence
           OR expression.practice_examples_payload->3->>'sentenceText' IS DISTINCT FROM asset.example4_sentence
           OR NOT (expression.practice_examples_payload->2 ? 'imageUrl')
           OR NOT (expression.practice_examples_payload->3 ? 'imageUrl')
           OR expression.practice_examples_payload->2->'imageUrl' IS DISTINCT FROM 'null'::jsonb
           OR expression.practice_examples_payload->3->'imageUrl' IS DISTINCT FROM 'null'::jsonb
    ) THEN
        RAISE EXCEPTION 'LAN-391 image mapping differs from V136 or image URLs are already set';
    END IF;

    UPDATE writing_expression expression
    SET practice_examples_payload = jsonb_set(
        jsonb_set(
            expression.practice_examples_payload,
            '{2,imageUrl}',
            to_jsonb('https://d19azau1un4t7r.cloudfront.net/content/scenario-expression-practice/sha256-2c07c44c76446b7c7f1d923f9a154365a3f49bd9cd59b6b0b3e2f52c58d80adc/scenario-order-'
                || asset.scenario_id || '/sql-row-' || lpad(asset.sql_values_row::text, 4, '0')
                || '/example-3/' || asset.example3_sha256 || '.webp'),
            false
        ),
        '{3,imageUrl}',
        to_jsonb('https://d19azau1un4t7r.cloudfront.net/content/scenario-expression-practice/sha256-2c07c44c76446b7c7f1d923f9a154365a3f49bd9cd59b6b0b3e2f52c58d80adc/scenario-order-'
            || asset.scenario_id || '/sql-row-' || lpad(asset.sql_values_row::text, 4, '0')
            || '/example-4/' || asset.example4_sha256 || '.webp'),
        false
    )
    FROM lan391_practice_image_map asset
    WHERE expression.id = asset.expression_id;

    GET DIAGNOSTICS affected_rows = ROW_COUNT;
    IF affected_rows <> 328 THEN
        RAISE EXCEPTION 'LAN-391 image URL update affected % expressions, expected 328', affected_rows;
    END IF;
END $$;
